import { LogicWrapper, MakeLogicType, actions, afterMount, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import {
    IntegrationAssigneeKind,
    IntegrationAssignees,
    IntegrationAssigneesQuery,
    fetchIntegrationAssignees,
} from 'lib/integrations/integrationAssignees'
import { teamLogic } from 'scenes/teamLogic'

export type ExternalIssueAssigneeKind = IntegrationAssigneeKind

export type ExternalIssueAssigneesLogicProps = Omit<IntegrationAssigneesQuery, 'search'>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface externalIssueAssigneesLogicValues {
    assignees: IntegrationAssignees | null
    assigneesLoading: boolean
    knownUserNames: Record<string, string>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface externalIssueAssigneesLogicActions {
    loadAssignees: (search: string) => string
    loadAssigneesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadAssigneesSuccess: (
        assignees: IntegrationAssignees,
        payload?: string
    ) => {
        assignees: IntegrationAssignees
        payload?: string
    }
    setSearch: (search: string) => {
        search: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface externalIssueAssigneesLogicMeta {
    key: string
}

export type externalIssueAssigneesLogicType = MakeLogicType<
    externalIssueAssigneesLogicValues,
    externalIssueAssigneesLogicActions,
    ExternalIssueAssigneesLogicProps,
    externalIssueAssigneesLogicMeta
>

export const externalIssueAssigneesLogic: LogicWrapper<externalIssueAssigneesLogicType> =
    kea<externalIssueAssigneesLogicType>([
        props({} as ExternalIssueAssigneesLogicProps),
        key((props) => `${props.integrationId}:${props.scope ?? ''}`),
        path((key) => ['products', 'error_tracking', 'components', 'externalIssueAssigneesLogic', key]),
        actions({
            setSearch: (search: string) => ({ search }),
        }),
        reducers({
            // A selected user can drop out of later search results, and the picker would then show their raw ID.
            knownUserNames: [
                {} as Record<string, string>,
                {
                    loadAssigneesSuccess: (state, { assignees }) => ({
                        ...state,
                        ...Object.fromEntries(assignees.users.map((user) => [user.id, user.name])),
                    }),
                },
            ],
        }),
        loaders(({ props }) => ({
            assignees: [
                null as IntegrationAssignees | null,
                {
                    loadAssignees: async (search: string, breakpoint) => {
                        const assignees = await fetchIntegrationAssignees(String(teamLogic.values.currentTeamId), {
                            ...props,
                            search,
                        })
                        breakpoint()
                        return assignees
                    },
                },
            ],
        })),
        listeners(({ actions }) => ({
            setSearch: async ({ search }, breakpoint) => {
                await breakpoint(300)
                actions.loadAssignees(search)
            },
        })),
        afterMount(({ actions }) => {
            actions.loadAssignees('')
        }),
    ])
